    private void platformControl()throws Exception{final android.media.AudioTrack raw=new android.media.AudioTrack.Builder().setAudioAttributes(new android.media.AudioAttributes.Builder().setUsage(android.media.AudioAttributes.USAGE_MEDIA).setContentType(android.media.AudioAttributes.CONTENT_TYPE_MUSIC).build()).setAudioFormat(new android.media.AudioFormat.Builder().setEncoding(android.media.AudioFormat.ENCODING_PCM_16BIT).setChannelMask(android.media.AudioFormat.CHANNEL_OUT_STEREO).setSampleRate(48000).build()).setBufferSizeInBytes(48000).setTransferMode(android.media.AudioTrack.MODE_STREAM).build();controlTrack=raw;final java.util.concurrent.atomic.AtomicBoolean running=new java.util.concurrent.atomic.AtomicBoolean(true);raw.setPlaybackParams(new android.media.PlaybackParams().allowDefaults().setSpeed(1.2f).setPitch(.75f));raw.play();Thread writer=new Thread(()->{short[] block=new short[2048];long frame=0;while(running.get()){for(int i=0;i<block.length;i+=2){short value=(short)Math.round(.2*Math.sin(2*Math.PI*1000*frame++/48000)*32767);block[i]=value;block[i+1]=value;}int offset=0;while(offset<block.length&&running.get()){int accepted=raw.write(block,offset,block.length-offset,android.media.AudioTrack.WRITE_BLOCKING);if(accepted<=0)return;offset+=accepted;}}},"Independent-AudioTrack-control");writer.start();try{sample("platform-direct-initial0.75",750);raw.setPlaybackParams(new android.media.PlaybackParams().allowDefaults().setSpeed(1.2f).setPitch(1.2f));sample("platform-direct-live1.2",1200);raw.pause();raw.flush();raw.setPlaybackParams(new android.media.PlaybackParams().allowDefaults().setSpeed(.8f).setPitch(1.4f));raw.play();sample("platform-direct-after-flush1.4",1400);}finally{running.set(false);raw.pause();raw.flush();writer.join(1500);raw.release();controlTrack=null;}}
    private void sample(String name,double expected)throws Exception{captureCommand("refresh",0);reply(103,7000);boolean settled=false;for(int attempt=0;attempt<(diagnostic()?2:4)&&!settled;attempt++){SystemClock.sleep(1000);int id=++request;captureCommand("sample",id);Bundle data=reply(101,7000);if(data.getInt("request")!=id)throw new AssertionError("Stale capture response");double rms=data.getDouble("rms"),frequency=data.getDouble("peakHz");settled=expected==0?rms<.0003:rms>.002&&Math.abs(frequency-expected)<Math.max(8,expected*.02);PcmPlayback.Snapshot snapshot=player.pcmSnapshot();android.media.PlaybackParams params=controlTrack!=null?controlTrack.getPlaybackParams():snapshot==null?((android.media.MediaPlayer)field(player,"media")).getPlaybackParams():null;captures.put(new JSONObject().put("case",name).put("window",attempt+1).put("captureRouteRefreshed",true).put("settled",settled).put("sourceHz",1000).put("expectedHz",expected).put("peakHz",frequency).put("rms",rms).put("frames",data.getInt("frames")).put("sampleRate",data.getInt("sampleRate")).put("captureUid",data.getInt("captureUid")).put("targetUid",data.getInt("targetUid")).put("actualRate",player.speed()).put("actualPitch",player.pitch()).put("nativeRate",params!=null?params.getSpeed():snapshot.speed).put("nativePitch",params!=null?params.getPitch():snapshot.pitch).put("sourcePosition",player.position()).put("controlHead",controlTrack==null?0:controlTrack.getPlaybackHeadPosition()).put("capturedAtElapsed",SystemClock.elapsedRealtime()).put("sourceGeneration",occurrence()).put("pcm",player.pcmActive()));}if(settled)check(true,expected==0?"Separate UID system output capture is silent after a paused PCM edit":"Actual post-AudioTrack capture measures "+expected+"Hz for "+name);else if(!diagnostic())check(false,"Actual post-AudioTrack capture measures "+expected+"Hz for "+name);}
