    private void approveConsent()throws Exception{long end=SystemClock.elapsedRealtime()+15000;while(SystemClock.elapsedRealtime()<end){Reply early=replies.peek();if(early!=null){if(early.code==199)throw new AssertionError(early.data.getString("error"));if(early.code==100)return;}AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow(),button=find(root,new String[]{"Start now","START NOW","START","Start","Начать","НАЧАТЬ","Start recording","Start sharing"});if(button!=null&&"com.android.systemui".contentEquals(button.getPackageName())){Rect bounds=new Rect();button.getBoundsInScreen(bounds);shell("input tap "+bounds.centerX()+" "+bounds.centerY());SystemClock.sleep(300);return;}SystemClock.sleep(80);}throw new AssertionError("Real system capture consent button absent: "+describe());}
    private static AccessibilityNodeInfo find(AccessibilityNodeInfo node,String[] labels){if(node==null)return null;CharSequence text=node.getText();for(String label:labels)if(text!=null&&label.contentEquals(text))return node;for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo match=find(node.getChild(i),labels);if(match!=null)return match;}return null;}
    private String describe(){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();return root==null?"null":root.toString();}
    private Bundle reply(int code,long timeout)throws Exception{long end=SystemClock.elapsedRealtime()+timeout;while(SystemClock.elapsedRealtime()<end){Reply reply=replies.poll(100,TimeUnit.MILLISECONDS);if(reply!=null){if(reply.code==199)throw new AssertionError("Actual playback capture: "+reply.data.getString("error"));if(reply.code!=code)throw new AssertionError("Unexpected capture event "+reply.code+", expected "+code);return reply.data;}}throw new AssertionError("Capture response timeout "+code);}
