    private void start(boolean play)throws Exception{onMain(()->{player.setVolume(.7f);player.setRepeat(0);player.setShuffle(false);player.setQueue(Arrays.asList(tone,tone,tone),0,play);});await(()->player.isPrepared(),10000,"Prepare generated native tone");if(play)await(()->player.isPlaying(),5000,"Play generated native tone");}
