    private long occurrence()throws Exception{return(Long)field(player,"sourceGeneration");}
    private static Object field(Object value,String name)throws Exception{Field field=value.getClass().getDeclaredField(name);field.setAccessible(true);return field.get(value);}
    private static boolean near(double value,double expected){return Math.abs(value-expected)<.0001;}
    private void await(Condition condition,long timeout,String message)throws Exception{long end=SystemClock.elapsedRealtime()+timeout;while(!condition.ready()){if(!cleaning&&player!=null&&!player.error().isEmpty())throw new AssertionError(message+": "+player.error());if(SystemClock.elapsedRealtime()>end)throw new AssertionError(message);SystemClock.sleep(30);}}
