    private void onMain(Task task)throws Exception{Throwable[] error={null};runOnMainSync(()->{try{task.run();}catch(Throwable failure){error[0]=failure;}});if(error[0] instanceof Error)throw(Error)error[0];if(error[0]!=null)throw(Exception)error[0];}
    private void wave(File file)throws Exception{int frames=48000*90,bytes=frames*4;try(OutputStream out=new BufferedOutputStream(new FileOutputStream(file))){out.write("RIFF".getBytes("US-ASCII"));le(out,bytes+36,4);out.write("WAVEfmt ".getBytes("US-ASCII"));le(out,16,4);le(out,1,2);le(out,2,2);le(out,48000,4);le(out,192000,4);le(out,4,2);le(out,16,2);out.write("data".getBytes("US-ASCII"));le(out,bytes,4);for(int i=0;i<frames;i++){short value=(short)Math.round(.2*Math.sin(2*Math.PI*1000*i/48000)*32767);le(out,value,2);le(out,value,2);}}}
    private static void le(OutputStream out,int value,int bytes)throws IOException{for(int i=0;i<bytes;i++)out.write(value>>>(i*8)&255);}
    private String shell(String command)throws IOException{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(command));ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] block=new byte[8192];int count;while((count=in.read(block))!=-1)out.write(block,0,count);return out.toString("UTF-8");}}
    private void capture(String name)throws Exception{SystemClock.sleep(500);Bitmap screenshot=getUiAutomation().takeScreenshot();if(screenshot!=null){try(FileOutputStream out=new FileOutputStream(new File(output,name))){screenshot.compress(Bitmap.CompressFormat.PNG,100,out);}screenshot.recycle();screenshots.put(name);}}
